import{_ as e}from"./chunks/channels-list.Cv5XW_0Z.js";import{_ as a,o,c as n,a2 as s}from"./chunks/framework.CPHNBVkq.js";const m=JSON.parse('{"title":"About Channels","description":"","frontmatter":{},"headers":[],"relativePath":"guide/channels.md","filePath":"guide/channels.md"}'),r={name:"guide/channels.md"};function h(l,t,g,i,c,d){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="about-channels" tabindex="-1">About Channels <a class="header-anchor" href="#about-channels" aria-label="Permalink to &quot;About Channels&quot;">​</a></h1><p>Channels are how you tell Corbi what you want to hear about. Each channel is a saved filter, and everything in your <a href="./pulse-feed.html">Pulse feed</a> comes from the channels you&#39;ve set up. No channels means an empty feed.</p><p>You can have as many channels as you like — for example, one for your team&#39;s sales activity and another for company-wide announcements.</p><p><img src="'+e+'" alt="Your channels in Settings"></p><h2 id="what-makes-up-a-channel" tabindex="-1">What makes up a channel <a class="header-anchor" href="#what-makes-up-a-channel" aria-label="Permalink to &quot;What makes up a channel&quot;">​</a></h2><p>When you create or edit a channel, you set four things:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Channel Name</strong></td><td>A label for you to recognize it by (3–50 characters).</td></tr><tr><td><strong>Channel Scope</strong></td><td>How wide the channel reaches — <strong>Broad</strong> or <strong>Narrow</strong>.</td></tr><tr><td><strong>Category</strong></td><td>The kind of business event the channel follows. Required.</td></tr><tr><td><strong>Channel Tags</strong></td><td>Optional. Specific items within the category to focus on.</td></tr></tbody></table><h2 id="category" tabindex="-1">Category <a class="header-anchor" href="#category" aria-label="Permalink to &quot;Category&quot;">​</a></h2><p>A <strong>category</strong> is the type of business event a channel follows. Categories are defined by your organization — common examples include Sales, Purchasing, Finance, HR, Customer Service, Warehouse, and Shop Floor.</p><p>Every channel must have exactly one category. The category also determines which <strong>tags</strong> are available to you, because tags come from that category&#39;s data.</p><h2 id="channel-tags" tabindex="-1">Channel Tags <a class="header-anchor" href="#channel-tags" aria-label="Permalink to &quot;Channel Tags&quot;">​</a></h2><p><strong>Tags</strong> let you focus a channel on specific things within its category — like a particular project, customer, or person. The tags available to you depend on the channel&#39;s <strong>category</strong>, so you choose the category first and then pick from the tags that belong to it.</p><p>Tags are optional. A channel with <strong>no tags</strong> follows its <strong>whole category</strong>. Once you add tags, the channel&#39;s <strong>scope</strong> decides how those tags combine — see <a href="#channel-scope">Channel Scope</a> next.</p><h2 id="channel-scope" tabindex="-1">Channel Scope <a class="header-anchor" href="#channel-scope" aria-label="Permalink to &quot;Channel Scope&quot;">​</a></h2><p>Scope doesn&#39;t filter on its own — it decides <strong>how the tags you&#39;ve chosen are combined</strong> when Corbi looks for matching updates:</p><ul><li><strong>Broad</strong> — an update is included if it matches <strong>any one</strong> of your tags. This <em>widens</em> the feed: more tags means more updates.</li><li><strong>Narrow</strong> — an update is included only if it matches <strong>all</strong> of your tags at once. This <em>tightens</em> the feed: more tags means fewer updates.</li></ul><p>Either way, an update must also belong to the channel&#39;s <strong>category</strong> — scope and tags only refine what&#39;s already in that category.</p><div class="tip custom-block"><p class="custom-block-title">Scope only matters with two or more tags</p><p>With <strong>no tags</strong>, Broad and Narrow behave the same: you get the whole category. With a <strong>single tag</strong>, they also behave the same. The difference only appears once you add a <strong>second tag</strong> — Broad asks for <em>any</em> match, Narrow asks for <em>every</em> match.</p></div><h2 id="how-scope-and-tags-work-together" tabindex="-1">How scope and tags work together <a class="header-anchor" href="#how-scope-and-tags-work-together" aria-label="Permalink to &quot;How scope and tags work together&quot;">​</a></h2><p>Think of your channel as three layers, each narrowing the feed a little more:</p><ol><li><strong>Category</strong> sets the baseline — only updates in the channel&#39;s category are ever considered.</li><li><strong>Tags</strong> pick out specific things within that category.</li><li><strong>Scope</strong> decides whether an update has to match <em>any</em> tag (Broad) or <em>every</em> tag (Narrow).</li></ol><table tabindex="0"><thead><tr><th>Your channel</th><th>Broad — match <strong>any</strong> tag</th><th>Narrow — match <strong>all</strong> tags</th></tr></thead><tbody><tr><td>Category only, no tags</td><td>Everything in the category</td><td>Everything in the category</td></tr><tr><td>Category + 1 tag</td><td>Updates with that tag</td><td>Updates with that tag</td></tr><tr><td>Category + tags <strong>A</strong> and <strong>B</strong></td><td>Updates tagged <strong>A</strong> <em>or</em> <strong>B</strong></td><td>Updates tagged <strong>A</strong> <em>and</em> <strong>B</strong></td></tr><tr><td>Category + tags <strong>A</strong>, <strong>B</strong>, <strong>C</strong></td><td>Updates with <em>any</em> of A/B/C</td><td>Updates with <em>all</em> of A, B, and C</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Example</p><p>A <strong>Sales</strong> channel tagged with the customers <strong>Acme</strong> and <strong>Globex</strong>:</p><ul><li><strong>Broad</strong> → updates about Acme <strong>or</strong> Globex — a wider feed covering both customers.</li><li><strong>Narrow</strong> → only updates that involve <strong>both</strong> Acme and Globex together — a much smaller feed.</li></ul><p>So if you want to follow several things at once, keep the channel <strong>Broad</strong>. If you&#39;re hunting for updates that sit at the intersection of several tags, switch it to <strong>Narrow</strong>.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./channels-create.html">Creating a Channel</a> — a step-by-step walkthrough.</li><li><a href="./channels-manage.html">Managing Channels</a> — edit, rename, or remove channels.</li></ul>',25)])])}const y=a(r,[["render",h]]);export{m as __pageData,y as default};
